stageCss:
#stage .qt-scene{ position:relative; width:100%; height:100%; display:flex; flex-direction:column; gap:14px; }

/* ============================== TOP STRIP ============================== */
#stage .qt-top{
  height:78px; flex-shrink:0; display:flex; align-items:center; gap:14px;
  padding:0 22px; border-radius:20px; white-space:nowrap;
  background:rgba(20,27,43,.78); border:1.5px solid var(--border);
}
#stage .qt-mark{
  width:46px; height:46px; border-radius:13px; flex-shrink:0;
  display:flex; align-items:center; justify-content:center;
  background:rgba(58,160,255,.14); border:1.5px solid rgba(58,160,255,.42); color:var(--accent-1);
}
#stage .qt-mark svg{ width:25px; height:25px; }
#stage .qt-app{
  color:var(--text-primary); font-family:var(--font-mono); font-size:21px; font-weight:600;
  overflow:hidden; text-overflow:ellipsis; min-width:0;
}
#stage .qt-size{ margin-left:auto; flex-shrink:0; display:flex; align-items:baseline; gap:8px; }
#stage .qt-size b{
  color:#fff; font-family:var(--font-mono); font-size:28px; font-weight:700;
  font-variant-numeric:tabular-nums; transition:color .3s ease;
}
#stage .qt-size.warn b{ color:var(--warn); }
#stage .qt-size.bad b{ color:var(--danger); }
#stage .qt-size i{ color:var(--text-dim); font-size:18px; font-weight:600; font-style:normal; }
#stage .qt-health{
  flex-shrink:0; display:flex; align-items:center; gap:8px; padding:7px 14px; border-radius:100px;
  border:1.5px solid rgba(63,185,80,.45); background:rgba(63,185,80,.1);
  transition:border-color .3s ease, background .3s ease;
}
#stage .qt-health i{
  width:10px; height:10px; border-radius:50%; background:var(--success);
  box-shadow:0 0 12px var(--success); animation:msd-breathe 2s ease-in-out infinite;
}
#stage .qt-health b{ color:var(--success); font-family:var(--font-mono); font-size:18px; font-weight:700; }
#stage .qt-health.warn{ border-color:rgba(240,166,74,.55); background:rgba(240,166,74,.12); }
#stage .qt-health.warn i{ background:var(--warn); box-shadow:0 0 12px var(--warn); animation-duration:.6s; }
#stage .qt-health.warn b{ color:var(--warn); }
#stage .qt-health.bad{ border-color:rgba(244,74,106,.55); background:rgba(244,74,106,.12); }
#stage .qt-health.bad i{ background:var(--danger); box-shadow:0 0 12px var(--danger); animation-duration:.45s; }
#stage .qt-health.bad b{ color:var(--danger); }

/* ============================= SCENE STACK ============================= */
#stage .qt-body{ position:relative; flex:1; min-height:0; }
#stage .qt-sc{
  position:absolute; inset:0; opacity:0; transform:scale(.986); pointer-events:none;
  transition:opacity .3s ease, transform .3s cubic-bezier(.22,1,.36,1);
}
#stage .qt-sc.on{ opacity:1; transform:none; }
#stage .qt-sc.whip{ animation:qt-whip .44s cubic-bezier(.19,1,.22,1); }

#stage .qt-board{ display:flex; flex-direction:column; gap:14px; height:100%; }

/* ------------------------------------------------------------ the topic -- */
#stage .qt-topic{
  height:172px; flex-shrink:0; display:flex; flex-direction:column; gap:14px; justify-content:center;
  padding:18px 22px; border-radius:26px;
  background:radial-gradient(circle at 50% 0%, rgba(58,160,255,.12), transparent 62%), rgba(20,27,43,.6);
  border:2px solid rgba(58,160,255,.45);
  transition:border-color .3s ease, box-shadow .3s ease;
}
#stage .qt-topic.bad{
  border-color:rgba(244,74,106,.65); box-shadow:0 0 0 1px rgba(244,74,106,.24), 0 0 56px rgba(244,74,106,.18);
  animation:qt-alert 1s ease-in-out infinite;
}
#stage .qt-topic-h{ display:flex; align-items:center; gap:13px; }
#stage .qt-topic-ic{
  width:46px; height:46px; border-radius:13px; flex-shrink:0; font-size:24px;
  display:flex; align-items:center; justify-content:center;
  background:rgba(58,160,255,.16); border:1.5px solid rgba(58,160,255,.4);
}
#stage .qt-topic-n{ color:#fff; font-size:26px; font-weight:800; letter-spacing:-.4px; white-space:nowrap; }
#stage .qt-topic-b{
  margin-left:auto; padding:8px 16px; border-radius:100px; white-space:nowrap;
  border:1.5px solid rgba(63,185,80,.5); background:rgba(63,185,80,.12); color:var(--success);
  font-family:var(--font-mono); font-size:17px; font-weight:700;
  transition:border-color .3s ease, background .3s ease, color .3s ease;
}
#stage .qt-topic-b.bad{ border-color:rgba(244,74,106,.6); background:rgba(244,74,106,.16); color:var(--danger); }
#stage .qt-meter{ height:20px; border-radius:10px; background:rgba(35,44,64,.9); overflow:hidden; }
#stage .qt-meter i{
  display:block; height:100%; width:8%; border-radius:10px;
  background:linear-gradient(90deg, var(--accent-1), var(--accent-cyan));
  transition:width .6s cubic-bezier(.22,1,.36,1), background .3s ease;
}
#stage .qt-meter i.warn{ background:linear-gradient(90deg,#F0A64A,#F4C46A); }
#stage .qt-meter i.bad{ background:linear-gradient(90deg,#F44A6A,#FF8FA3); animation:qt-alert .9s ease-in-out infinite; }
#stage .qt-topic-f{
  display:flex; align-items:center; justify-content:space-between;
  color:var(--text-dim); font-family:var(--font-mono); font-size:18px; font-weight:600; white-space:nowrap;
}

/* ------------------------------------------------------- subscriptions --- */
#stage .qt-subs{ flex:1; min-height:0; display:flex; align-items:center; gap:11px; }
#stage .qt-sub{
  flex:1; min-width:0; height:240px; display:flex; flex-direction:column; gap:9px; justify-content:center;
  padding:14px 13px; border-radius:22px;
  background:linear-gradient(180deg, var(--bg-panel), var(--bg-panel-2));
  border:1.5px solid var(--border);
  transition:border-color .3s ease, box-shadow .3s ease, opacity .3s ease;
}
#stage .qt-sub.ok{ border-color:rgba(63,185,80,.5); }
#stage .qt-sub.warn{ border-color:rgba(240,166,74,.55); box-shadow:0 0 0 1px rgba(240,166,74,.18), 0 0 36px rgba(240,166,74,.12); }
#stage .qt-sub.bad{
  border-color:rgba(244,74,106,.65); box-shadow:0 0 0 1px rgba(244,74,106,.24), 0 0 40px rgba(244,74,106,.16);
  animation:qt-alert 1s ease-in-out infinite;
}
#stage .qt-s-h{ display:flex; align-items:center; gap:9px; }
#stage .qt-s-ic{ font-size:22px; flex-shrink:0; }
#stage .qt-s-h b{
  color:#fff; font-family:var(--font-mono); font-size:18px; font-weight:700;
  white-space:nowrap; overflow:hidden; text-overflow:ellipsis;
}
#stage .qt-filter{
  padding:7px 10px; border-radius:9px; white-space:nowrap; overflow:hidden; text-overflow:ellipsis;
  background:rgba(58,160,255,.12); border:1px solid rgba(58,160,255,.35); color:var(--accent-1);
  font-family:var(--font-mono); font-size:14px; font-weight:600;
  transition:background .3s ease, border-color .3s ease, color .3s ease;
}
#stage .qt-filter.bad{ background:rgba(244,74,106,.12); border-color:rgba(244,74,106,.4); color:var(--danger); }
#stage .qt-s-n{ display:flex; align-items:baseline; gap:7px; }
#stage .qt-s-n b{
  color:#fff; font-family:var(--font-mono); font-size:28px; font-weight:800;
  font-variant-numeric:tabular-nums; line-height:1;
}
#stage .qt-s-n i{ color:var(--text-dim); font-size:15px; font-weight:600; font-style:normal; }
#stage .qt-sub.bad .qt-s-n b{ color:var(--danger); }
#stage .qt-sub.warn .qt-s-n b{ color:var(--warn); }
#stage .qt-s-d{
  color:var(--text-dim); font-family:var(--font-mono); font-size:15px; font-weight:600;
  white-space:nowrap; overflow:hidden; text-overflow:ellipsis;
}

/* --------------------------------------------------------- the trap band -- */
#stage .qt-trap{ position:relative; height:230px; flex-shrink:0; }
#stage .qt-t{
  position:absolute; inset:0; opacity:0; pointer-events:none;
  display:flex; flex-direction:column; align-items:center; justify-content:center; gap:11px;
  padding:14px 18px; border-radius:24px;
  background:rgba(20,27,43,.62); border:1.5px solid var(--border);
  transition:opacity .3s ease;
}
#stage .qt-t.on{ opacity:1; }
#stage .qt-t-h{ color:#fff; font-size:21px; font-weight:800; letter-spacing:-.3px; white-space:nowrap; }
#stage .qt-t-b{
  padding:7px 16px; border-radius:100px; white-space:nowrap;
  border:1.5px solid rgba(240,166,74,.5); background:rgba(240,166,74,.12); color:var(--warn);
  font-family:var(--font-mono); font-size:16px; font-weight:700;
}
#stage .qt-t-b.bad{ border-color:rgba(244,74,106,.55); background:rgba(244,74,106,.14); color:var(--danger); }
#stage .qt-t-b.ok{ border-color:rgba(63,185,80,.5); background:rgba(63,185,80,.14); color:var(--success); }
#stage .qt-code{ display:flex; flex-direction:column; gap:4px; align-items:center; }
#stage .qt-code-l{
  color:var(--code-plain); font-family:var(--font-mono); font-size:15px; font-weight:600; white-space:nowrap;
}
#stage .qt-code-l.warn{ color:var(--warn); }
#stage .qt-chips{ display:flex; align-items:center; gap:8px; flex-wrap:wrap; justify-content:center; }
#stage .qt-chips i{
  padding:8px 12px; border-radius:10px; white-space:nowrap; font-style:normal;
  background:rgba(139,149,167,.1); border:1.5px solid rgba(139,149,167,.3); color:var(--text-dim);
  font-family:var(--font-mono); font-size:15px; font-weight:600;
}
#stage .qt-chips i.ok{ background:rgba(63,185,80,.12); border-color:rgba(63,185,80,.4); color:#bff0c4; }
#stage .qt-chips i.warn{ background:rgba(240,166,74,.12); border-color:rgba(240,166,74,.4); color:var(--warn); }
#stage .qt-chips i.bad{ background:rgba(244,74,106,.12); border-color:rgba(244,74,106,.45); color:#ffd0d9; }

#stage .qt-strip{
  height:72px; flex-shrink:0; display:flex; align-items:center; gap:16px;
  padding:0 22px; border-radius:20px;
  background:rgba(20,27,43,.7); border:1.5px solid var(--border);
  transition:border-color .3s ease, background .3s ease;
}
#stage .qt-strip b{
  padding:6px 15px; border-radius:8px; flex-shrink:0;
  background:rgba(58,160,255,.16); color:var(--accent-1);
  font-family:var(--font-mono); font-size:18px; font-weight:800; letter-spacing:2px;
}
#stage .qt-strip span{ color:var(--text-primary); font-size:22px; font-weight:600; line-height:1.3; }
#stage .qt-strip.bad{ border-color:rgba(244,74,106,.5); background:rgba(244,74,106,.1); }
#stage .qt-strip.bad b{ background:rgba(244,74,106,.2); color:var(--danger); }
#stage .qt-strip.good{ border-color:rgba(63,185,80,.45); background:rgba(63,185,80,.09); }
#stage .qt-strip.good b{ background:rgba(63,185,80,.2); color:var(--success); }

/* ======================== SCENE 2 · HONESTLY, WHICH ==================== */
#stage .qt-split{ display:flex; gap:16px; height:100%; }
#stage .qt-col{
  flex:1; display:flex; flex-direction:column; align-items:center; justify-content:center; gap:16px;
  padding:26px 18px; border-radius:28px; text-align:center;
}
#stage .qt-col.q{ background:rgba(20,27,43,.6); border:2px solid rgba(58,160,255,.45); }
#stage .qt-col.t{
  background:radial-gradient(circle at 50% 0%, rgba(63,185,80,.14), transparent 62%), rgba(20,27,43,.6);
  border:2px solid rgba(63,185,80,.5);
}
#stage .qt-col-h{ font-family:var(--font-mono); font-size:19px; font-weight:800; letter-spacing:2px; }
#stage .qt-col.q .qt-col-h{ color:var(--accent-1); }
#stage .qt-col.t .qt-col-h{ color:var(--success); }
#stage .qt-col-ic{ font-size:54px; line-height:1; }
#stage .qt-col.t .qt-col-ic{ animation:msd-breathe 2.4s ease-in-out infinite; }
#stage .qt-col-list{ width:100%; display:flex; flex-direction:column; gap:10px; }
#stage .qt-row{
  padding:14px 10px; border-radius:13px;
  background:rgba(14,20,32,.7); border:1.5px solid var(--border); color:var(--text-dim);
  font-size:20px; font-weight:600; line-height:1.25;
}
#stage .qt-row b{ color:#fff; font-weight:800; }
#stage .qt-col-x{
  width:100%; padding:13px 10px; border-radius:14px;
  background:rgba(58,160,255,.12); border:1.5px solid rgba(58,160,255,.45); color:var(--accent-1);
  font-family:var(--font-mono); font-size:16px; font-weight:700; line-height:1.3;
}
#stage .qt-col-x.ok{ background:rgba(63,185,80,.12); border-color:rgba(63,185,80,.45); color:var(--success); }

/* ========================== SCENE 3 · THE PAYOFF ======================= */
#stage .qt-final{
  height:100%; display:flex; flex-direction:column; align-items:center; justify-content:center; gap:18px;
  text-align:center;
}
#stage .qt-badge{
  width:130px; height:130px; border-radius:36px; font-size:60px;
  display:flex; align-items:center; justify-content:center;
  background:linear-gradient(160deg, rgba(63,185,80,.28), rgba(34,211,238,.14));
  border:2px solid rgba(63,185,80,.6);
  box-shadow:0 0 0 1px rgba(63,185,80,.3), 0 0 80px rgba(63,185,80,.3);
  animation:msd-breathe 2.4s ease-in-out infinite;
}
#stage .qt-badge-l{ color:var(--success); font-family:var(--font-mono); font-size:19px; font-weight:800; letter-spacing:3px; }
#stage .qt-fin-h{ color:#fff; font-size:60px; font-weight:900; line-height:1.12; letter-spacing:-1.8px; }
#stage .qt-fin-h em{ font-style:normal; color:var(--accent-cyan); }
#stage .qt-fin-row{ display:flex; flex-wrap:wrap; justify-content:center; gap:12px; }
#stage .qt-fin-p{
  padding:12px 20px; border-radius:100px; white-space:nowrap;
  background:rgba(20,27,43,.8); border:1.5px solid rgba(63,185,80,.42); color:var(--text-primary);
  font-size:21px; font-weight:700;
}
#stage .qt-save{
  margin-top:8px; padding:18px 26px; border-radius:20px; max-width:860px;
  background:linear-gradient(90deg, rgba(63,185,80,.18), rgba(34,211,238,.14));
  border:1.5px solid rgba(63,185,80,.5); color:#fff;
  font-size:25px; font-weight:700; line-height:1.35;
}
#stage .qt-save.ping{ animation:msd-punch .4s cubic-bezier(.22,1,.36,1); }

/* ============================== KEYFRAMES ============================== */
@keyframes qt-alert{
  0%,100%{ box-shadow:0 0 0 1px rgba(244,74,106,.3), 0 0 40px rgba(244,74,106,.16); }
  50%{ box-shadow:0 0 0 1px rgba(244,74,106,.55), 0 0 80px rgba(244,74,106,.3); }
}
@keyframes qt-whip{
  0%{ transform:translateX(220px) scale(1.04); filter:blur(16px); opacity:0; }
  55%{ filter:blur(3px); opacity:1; }
  100%{ transform:none; filter:blur(0); opacity:1; }
}

