var QT = window.__QT || (window.__QT = {});
QT.setFill = function(pct){ MSD.q('#qt-fill').style.width = pct + '%'; };

MSD.cls('.qt-sc', 'on', false);
MSD.cls('#qt-sc-board', 'on', true);
MSD.q('#qt-app').textContent = 'orders · topic · 4 subscriptions';
MSD.cls('#qt-size', 'warn', false);
MSD.cls('#qt-size', 'bad', false);
MSD.q('#qt-size-n').textContent = '0.1';
MSD.cls('#qt-health', 'warn', false);
MSD.cls('#qt-health', 'bad', false);
MSD.q('#qt-health-t').textContent = 'healthy';

MSD.cls('#qt-topic', 'bad', false);
MSD.cls('#qt-topic-b', 'bad', false);
MSD.q('#qt-topic-b').textContent = 'publisher OK';
MSD.cls('#qt-fill', 'warn', false);
MSD.cls('#qt-fill', 'bad', false);
QT.setFill(8);
MSD.q('#qt-topic-l').textContent = 'one copy stored · subscriptions hold references';

MSD.cls('.qt-sub', 'ok', false);
MSD.cls('.qt-sub', 'warn', false);
MSD.cls('.qt-sub', 'bad', false);
MSD.cls('.qt-filter', 'bad', false);
MSD.q('#qt-s-1-f').textContent = "region = 'IN'";
MSD.q('#qt-s-2-f').textContent = 'no filter';
MSD.q('#qt-s-3-f').textContent = 'no filter';
MSD.q('#qt-s-4-f').textContent = 'no filter';
['1', '2', '3', '4'].forEach(function(i){
  MSD.q('#qt-s-' + i + '-n').textContent = '0';
  MSD.q('#qt-s-' + i + '-d').textContent = 'DLQ 0';
});
MSD.cls('.qt-t', 'on', false);
MSD.hide('.qt-row');
MSD.hide('.qt-fin-p');
MSD.cls('#qt-strip', 'bad', false);
MSD.cls('#qt-strip', 'good', false);
MSD.q('#qt-strip-l').textContent = 'DAY 1';
MSD.q('#qt-strip-t').textContent = 'You chose a topic because several teams needed the event. That was right.';

MSD.after(500, function(){ MSD.cls('.qt-sub', 'ok', true); MSD.punch('#qt-topic', 1); MSD.sfx.blip(1); });
MSD.after(1600, function(){ MSD.punch('#qt-s-1', 2); MSD.punch('#qt-s-4', 4); MSD.sfx.blip(3); });

var QT = window.__QT;

MSD.cls('.qt-sc', 'on', false);
MSD.cls('#qt-sc-board', 'on', true);
MSD.cls('.qt-t', 'on', false);
MSD.cls('.qt-sub', 'ok', true);
MSD.q('#qt-app').textContent = 'orders · topic · incident';
MSD.cls('#qt-strip', 'good', false);
MSD.cls('#qt-strip', 'bad', true);
MSD.q('#qt-strip-l').textContent = 'PAGED';
MSD.q('#qt-strip-t').textContent = 'The service that broke is the one that never changed. That is the clue.';

MSD.after(300, function(){
  QT.setFill(72);
  MSD.cls('#qt-fill', 'warn', true);
  MSD.cls('#qt-size', 'warn', true);
  MSD.q('#qt-size-n').textContent = '0.7';
  MSD.cls('#qt-health', 'warn', true);
  MSD.q('#qt-health-t').textContent = 'filling';
  MSD.sfx.error();
});
MSD.after(1300, function(){
  QT.setFill(100);
  MSD.cls('#qt-fill', 'warn', false);
  MSD.cls('#qt-fill', 'bad', true);
  MSD.cls('#qt-size', 'warn', false);
  MSD.cls('#qt-size', 'bad', true);
  MSD.q('#qt-size-n').textContent = '1.0';
  MSD.cls('#qt-topic', 'bad', true);
  MSD.q('#qt-topic-b').textContent = 'QuotaExceededException';
  MSD.cls('#qt-topic-b', 'bad', true);
  MSD.cls('#qt-health', 'warn', false);
  MSD.cls('#qt-health', 'bad', true);
  MSD.q('#qt-health-t').textContent = 'sends failing';
  MSD.shake('#qt-topic');
  MSD.sfx.thud();
});
MSD.after(2200, function(){
  MSD.q('#qt-strip-l').textContent = 'WHY';
  MSD.q('#qt-strip-t').textContent = 'Nobody deployed anything. One subscription simply stopped being read.';
});

var QT = window.__QT;

MSD.cls('.qt-sc', 'on', false);
MSD.cls('#qt-sc-board', 'on', true);
MSD.cls('.qt-t', 'on', false);
MSD.cls('#qt-topic', 'bad', true);
MSD.cls('#qt-strip', 'good', false);
MSD.cls('#qt-strip', 'bad', true);
MSD.q('#qt-strip-l').textContent = 'TRAP 1';
MSD.q('#qt-strip-t').textContent = 'Your filter works. The rule sitting next to it also works — on everything.';

MSD.after(300, function(){
  MSD.cls('#qt-t-1', 'on', true);
  MSD.sfx.blip(1);
});
MSD.after(1300, function(){
  MSD.q('#qt-s-1-f').textContent = "region='IN' + \u0024Default";
  MSD.cls('#qt-s-1-f', 'bad', true);
  MSD.cls('#qt-s-1', 'ok', false);
  MSD.cls('#qt-s-1', 'warn', true);
  MSD.q('#qt-s-1-n').textContent = '9,410';
  MSD.q('#qt-s-1-d').textContent = 'matches every region';
  MSD.punch('#qt-s-1', 3);
  MSD.sfx.error();
});
MSD.after(2300, function(){
  MSD.q('#qt-strip-l').textContent = 'FIX';
  MSD.q('#qt-strip-t').textContent = 'RemoveRuleAsync("$Default") — or create the subscription with your rule.';
});

var QT = window.__QT;

MSD.cls('.qt-sc', 'on', false);
MSD.cls('#qt-sc-board', 'on', true);
MSD.cls('.qt-t', 'on', false);
MSD.cls('#qt-topic', 'bad', true);
MSD.cls('#qt-s-1', 'warn', true);
MSD.cls('#qt-strip', 'good', false);
MSD.cls('#qt-strip', 'bad', true);
MSD.q('#qt-strip-l').textContent = 'TRAP 2';
MSD.q('#qt-strip-t').textContent = 'This is the one that pages you, and it is nobody-on-call\'s subscription.';

MSD.after(300, function(){
  MSD.cls('#qt-t-2', 'on', true);
  MSD.sfx.blip(2);
});
MSD.after(1200, function(){
  MSD.cls('#qt-s-4', 'ok', false);
  MSD.cls('#qt-s-4', 'bad', true);
  MSD.q('#qt-s-4-n').textContent = '4.1M';
  MSD.q('#qt-s-4-d').textContent = 'last read · 14 March';
  MSD.shake('#qt-s-4');
  MSD.sfx.error();
});
MSD.after(2100, function(){
  MSD.q('#qt-topic-l').textContent = 'the message survives until the LAST subscription completes it';
  MSD.punch('#qt-topic', 4);
  MSD.sfx.thud();
});
MSD.after(2700, function(){
  MSD.q('#qt-strip-l').textContent = 'FIX';
  MSD.q('#qt-strip-t').textContent = 'Set a TTL per subscription, and AutoDeleteOnIdle on the ones nobody owns.';
});

var QT = window.__QT;

MSD.cls('.qt-sc', 'on', false);
MSD.cls('#qt-sc-board', 'on', true);
MSD.cls('.qt-t', 'on', false);
MSD.cls('#qt-topic', 'bad', true);
